pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 increase, uint256 lockTime, uint256 collectAmt, uint256 value) public {
        // ADMISSIBLE domain: positive amounts, minSum fits uint256, no overflow in operations we do
        vm.assume(minSum > 0);
        vm.assume(increase > 0);
        vm.assume(minSum + increase > minSum); // no overflow
        vm.assume(collectAmt > 0);
        vm.assume(value >= collectAmt);

        // Initialize contract with a MinSum and register it
        c.Initialized();
        c.SetMinSum(minSum);

        // Set up an account that can collect
        address alice = address(0x1000);
        vm.deal(alice, value);
        vm.prank(alice);
        c.Put{value: value}(lockTime);
        vm.warp(block.timestamp + lockTime + 1);

        // Record MinSum before any possible change
        uint256 minSumBefore = c.MinSum();

        // Now call SetMinSum again with an increased value if the mutant allows it
        c.SetMinSum(minSum + increase);

        // Record MinSum after the call
        uint256 minSumAfter = c.MinSum();

        // Property: MinSum can never increase after the first SetMinSum.
        // The reference reverts on the second SetMinSum (so minSumAfter == minSumBefore).
        // The mutant updates it, so minSumAfter > minSumBefore for some input.
        assertTrue(minSumAfter == minSumBefore);
    }
}

