        vm.assume(newMin < initialMin); // mutant can decrease MinSum
        vm.assume(collectAmt >= initialMin); // need enough to collect under original rule
        vm.assume(lockTime > 0);

        // Setup: initialize min, then finalize initialization
        vm.prank(address(this));
        c.SetMinSum(initialMin);
        vm.prank(address(this));
