contract Reenterer {
    C public target;
    bool private reentered;

    constructor(address _target) {
        target = C(_target);
        reentered = false;
    }

    function attack(uint256 amt, uint256 lockTime) external payable {
        // Put funds into the contract
        target.Put{value: msg.value}(lockTime);
        // Trigger Collect, which will call back into this contract
        target.Collect(amt);
    }

    receive() external payable {
        // Re-entrant call that attempts to change MinSum during Collect
        if (!reentered) {
            reentered = true;
            // This call can succeed only if the reentrancy guard is broken (i.e., the mutant)
            target.SetMinSum(0);
            reentered = false;
        }
    }
}

